'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Spec-literal reference: recursive DFS, FIFO queue, constraint lists, no pruning.
function reference(registry, root) {
  function step(selected, constraints, queue, cursor) {
    if (cursor === queue.length) return Object.fromEntries(selected);
    const name = queue[cursor];
    if (selected.has(name)) return step(selected, constraints, queue, cursor + 1);
    const ranges = constraints.get(name) || [];
    const versions = Object.keys(registry[name] || {})
      .filter(v => ranges.every(r => satisfies(v, r)))
      .sort((a, b) => compare(b, a));
    for (const v of versions) {
      const sel = new Map(selected).set(name, v);
      const cons = new Map([...constraints].map(([k, l]) => [k, [...l]]));
      const q = [...queue];
      let ok = true;
      for (const [dep, range] of Object.entries(registry[name][v])) {
        if (!cons.has(dep)) cons.set(dep, []);
        cons.get(dep).push(range);
        q.push(dep);
        if (sel.has(dep) && !satisfies(sel.get(dep), range)) { ok = false; break; }
      }
      if (!ok) continue;
      const found = step(sel, cons, q, cursor + 1);
      if (found) return found;
    }
    return null;
  }
  const constraints = new Map();
  const queue = [];
  for (const [name, range] of Object.entries(root)) {
    if (!constraints.has(name)) constraints.set(name, []);
    constraints.get(name).push(range);
    queue.push(name);
  }
  return step(new Map(), constraints, queue, 0);
}

