for (let t = 0; t < 20000; t += 1) {
  const names = ['a', 'b', 'c', 'd', 'e', 'f'].slice(0, 2 + rand(5));
  const registry = {};
  for (const name of names) {
    if (rand(10) === 0) continue; // missing package
    registry[name] = {};
    for (const v of VERS) {
      if (rand(2)) continue;
      const deps = {};
      for (let k = rand(3); k > 0; k -= 1) deps[names[rand(names.length)]] = range();
      registry[name][v] = deps;
